class Solution {
public:
    int makeTheIntegerZero(int num1, int num2) {
        for (long long k = 1; k <= 60; ++k) {
            long long val = (long long)num1 - k * num2;
            if (val < k) continue;
            if (__builtin_popcountll(val) <= k) return k;
        }
        return -1;
    }
};

class Solution {
    public int makeTheIntegerZero(int num1, int num2) {
        for (long k = 1; k <= 60; k++) {
            long val = (long) num1 - k * num2;
            if (val < k) continue;
            if (Long.bitCount(val) <= k) return (int) k;
        }
        return -1;
    }
}

var makeTheIntegerZero = function(num1, num2) {
    const bigNum1 = BigInt(num1);
    const bigNum2 = BigInt(num2);
    for (let k = 1n; k <= 60n; k++) {
        const val = bigNum1 - k * bigNum2;
        if (val < k) continue;
        let bits = 0n;
        let temp = val;
        while (temp > 0n) {
            bits += temp & 1n;
            temp >>= 1n;
        }
        if (bits <= k) return Number(k);
    }
    return -1;
};
